        const fl_value fl_t50170 = imya;
        const fl_value fl_t50171 = fl_number(nomer.as.number + 1.0);
        imena = h;
        imya = fl_t50170;
        nomer = fl_t50171;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Место в именах", error));
        continue;
